    from jsonb_populate_record(null::public.reading_articles, $seed${"slug":"a1-the-blue-shoes","title":"The Blue Shoes","level":"A1","status":"published","sort_order":200,"metadata":{"genre":"shop dialogue","word_count":109},"summary":"A customer reads a shop note and learns how to change a pair of shoes.","content_markdown":"Lola buys blue shoes for work. At home she tries them on again. They are too small. She wants the same shoes in a larger size. She reads the note on her receipt.\n\n**From the shop:** You can change clean shoes within seven days. Bring the shoes, the box and the receipt. Come to the desk by the door.\n\nOn Saturday Lola takes the shoes to the shop. The man at the desk looks for a larger blue pair. He only has black shoes in her size today. He says, “We can get blue ones on Tuesday.” Lola wants the blue shoes, so she says she will come back.","category":"Everyday","theme":"shoe exchange","tone":"sky","read_time_minutes":2,"is_hot":false,"questions":[{"id":"q1","type":"mcq","prompt":"Why does Lola go back to the shop?","options":["To buy shoes for a friend","To look for work","To get another receipt","To change her shoes for a larger pair"],"answer_index":3,"explanation":"The blue shoes are too small. Lola wants the same shoes in a larger size.","skill":"reading.main_idea"},{"id":"q2","type":"mcq","prompt":"What must Lola bring to change the shoes?","options":["The shoes and a card","Her work bag and the receipt","Only the shoes and the box","The shoes, the box and the receipt"],"answer_index":3,"explanation":"The note tells her to bring the shoes, the box and the receipt.","skill":"reading.detail"},{"id":"q3","type":"mcq","prompt":"What colour does the man have in Lola’s size on Saturday?","options":["Black","White","Brown","Blue"],"answer_index":0,"explanation":"He only has black shoes in her size that day.","skill":"reading.detail"},{"id":"q4","type":"mcq","prompt":"Why does Lola plan to come back on Tuesday?","options":["She can get the larger blue shoes then.","Her black shoes will be ready then.","The shop is closed on Saturday.","She forgot the receipt."],"answer_index":0,"explanation":"The man says he can get blue shoes on Tuesday. Lola wants blue ones.","skill":"reading.inference"},{"id":"q5","type":"tfng","variant":"tfng","prompt":"The shop asks customers to come to the desk by the door.","answer":"true","explanation":"The note says, “Come to the desk by the door.”","skill":"reading.detail"},{"id":"q6","type":"gap","prompt":"Complete the sentences with words from the passage.","text":"You can change clean shoes within ___ days.","answers":[["seven"]],"word_bank":["three","seven","ten"],"explanation":"The receipt says “within seven days.”","skill":"reading.detail"}]}$seed$::jsonb) r
