  else
    insert into public.reading_articles (slug, title, level, status, sort_order, metadata, summary, content_markdown, category, theme, tone, read_time_minutes, is_hot, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.content_markdown, r.category, r.theme, r.tone, r.read_time_minutes, r.is_hot, r.questions, v_product_reading, v_en_id
    from jsonb_populate_record(null::public.reading_articles, $seed${"slug":"c1-a-street-you-hear-before-you-see","title":"A Street You Hear Before You See","level":"C1","status":"published","sort_order":200,"metadata":{"genre":"reported essay","word_count":427},"summary":"An urban design team learns what familiar sounds can and cannot do for people navigating a street.","content_markdown":"Standing on Bramble Street, designer Leila Orr hears two doors close. One gives a thin metal click; the other produces a short rattle that travels through the pavement grille. She had walked past both entrances for years without noticing the difference. The people who brought her here were testing what happened to familiar cues after the council rebuilt a junction. Some used canes or relied heavily on sound. Others said the rebuilt crossing simply felt harder to recognise in a crowd.\n\nThe reconstruction had kept the official crossing in almost the same location. Its new canopy, however, reflected the sound of the automatic doors towards the crossing. One participant recalled using the low rumble of a bakery fan to tell when she had reached the end of a partly covered stretch of pavement. Now the fan sounded equally loud on either side of the turn. The sound had not vanished. Its position had become harder to judge.\n\nThere was a temptation to list these sounds as additional street furniture. Mark the fan and the doors on a diagram, preserve them, and the problem might appear solved. Orr’s team resisted that conclusion. A fan stops when a business closes, and a door makes no sound until somebody uses it. One participant treated the fan as a useful clue on weekday mornings. Another, who crossed the street after work, had never heard it. A landmark can be dependable for one person without being available to everyone.\n\nThe team asked participants to walk a route more than once. On the first walk, they followed their usual habits. On a later walk, the researchers asked them to explain which clues they had combined at each decision. A participant might pause for the doors, align herself with the edge of the pavement and then wait for the recognised signal at the crossing. A sound that helped her locate the right stretch of street was not necessarily the cue that told her it was safe to cross.\n\nThe council kept the commissioned crossing signals and adjusted a section of the canopy so echoes did not travel as far. It also asked the design team to repeat the walks at other times of day. The exercise had changed the sort of question the council asked. Instead of recording only whether each feature had remained in place, it began asking whether the relationship between features was still legible to people using the street. The crossing was in nearly the same place on the plan. That fact had concealed changes in the experience of getting there.","category":"Society","theme":"sound landmarks in street design","tone":"lime","read_time_minutes":3,"is_hot":false,"questions":[{"id":"q1","type":"mcq","prompt":"What does the passage argue should be evaluated after a reconstruction?","options":["Whether every informal sound can be replaced by a commissioned signal","Whether people can still interpret cues in combination as they move through the street","Whether a sound remains audible at the point where it was first recorded","Whether the physical position of the official crossing remains unchanged"],"answer_index":1,"explanation":"The team finds that usability depends on which cues can be located and combined, even when the crossing position is unchanged.","skill":"reading.main_idea"},{"id":"q2","type":"mcq","prompt":"Why did the bakery fan become less useful to one participant?","options":["It became quieter than the automatic doors.","It seemed equally loud on both sides of a turn.","It was replaced by an official signal.","The business had stopped using it during visits."],"answer_index":1,"explanation":"The canopy changed how sound travelled and the fan no longer marked the turn clearly.","skill":"reading.detail"},{"id":"q3","type":"mcq","prompt":"Why would preserving every listed sound be an incomplete solution?","options":["The participants were able to ignore all sounds once diagrams were available.","It would prevent the council from recording when doors were in use.","Only participants who cross at night use acoustic landmarks.","A sound can be intermittent or unavailable on somebody’s usual route and schedule."],"answer_index":3,"explanation":"The fan varies by opening hours, and a door can only be heard when used. Neither clue can serve everyone at all times.","skill":"reading.inference"},{"id":"q4","type":"mcq","prompt":"What does “legible” mean in the last paragraph?","options":["Legally permitted","Visible from beyond the junction","Recorded on a large sign","Coherent enough for people to interpret"],"answer_index":3,"explanation":"It refers to being able to make sense of the features and how they relate during a journey.","skill":"reading.vocabulary"},{"id":"q5","type":"tfng","variant":"tfng","prompt":"The walks established that the bakery fan could serve as the crossing safety signal.","answer":"false","explanation":"The text explicitly distinguishes a cue that locates a stretch of street from the recognised signal that indicates when to cross.","skill":"reading.detail"},{"id":"q6","type":"gap","prompt":"Complete the sentences with words from the passage.","text":"The new ___ carried sound towards the crossing. The team asked people to combine ordinary clues with an official ___.","answers":[["canopy"],["signal"]],"word_bank":["canopy","rattle","signal","pavement"],"explanation":"Paragraph 2 gives the reflecting structure. Paragraph 4 distinguishes informal cues from the signal at the crossing.","skill":"reading.detail"},{"id":"q7","type":"headings","prompt":"Choose the best heading for each numbered paragraph.","options":["Observing how clues work together","Why sound clues vary among users","The unexpected effect of a physical change","A new criterion for judging the redesign","Why ordinary street sounds should be removed"],"items":[{"id":"p2","paragraph":2,"answer_index":2},{"id":"p3","paragraph":3,"answer_index":1},{"id":"p4","paragraph":4,"answer_index":0},{"id":"p5","paragraph":5,"answer_index":3}],"explanation":"Paragraph 2 describes changed sound location, paragraph 3 questions reliability, paragraph 4 examines combinations, and paragraph 5 moves from preserved features to the relationships between them.","skill":"reading.main_idea"}]}$seed$::jsonb) r
