    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a1-collect-a-blue-scarf","title":"Collect a blue scarf","level":"A1","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Nora","Clerk"]},"summary":"A lost-property worker asks about a scarf and explains how to collect it.","transcript_text":"Nora: Hello. I left my scarf on the bus.\nClerk: What colour is it?\nNora: It's blue, with white stars.\nClerk: I have a blue scarf with white stars here. Can you come this afternoon?\nNora: Yes. Where are you?\nClerk: At the bus station. Ask for Desk Two. Bring your bus ticket, please.\nNora: Thank you. I'll come at four.","category":"Everyday","accent":"general","speed_label":"slow","speed_wpm":100,"duration_seconds":37,"audio_url":null,"focus_skill":"detail","tags":["everyday","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"What is on the scarf?","options":["Red circles","Blue flowers","Black lines","White stars"],"answer_index":3,"explanation":"Nora describes a blue scarf with white stars."},{"id":"q2","type":"mcq","prompt":"Which desk should Nora go to?","options":["Desk Two","Desk Three","Desk Four","Desk Five"],"answer_index":0,"explanation":"The clerk tells her to ask for Desk Two."},{"id":"q3","type":"mcq","prompt":"What should Nora bring?","options":["A photo","Her bus ticket","A bag","Some money"],"answer_index":1,"explanation":"The clerk asks her to bring her bus ticket."}]}$seed$::jsonb) r
