  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a1-imperatives-at-a-craft-table","title":"Imperatives at a craft table","level":"A1","status":"published","sort_order":320,"metadata":{},"focus_area":"imperative-instructions","explanation_text":"Use an imperative to tell someone what to do. Use the base form of the verb in an affirmative imperative, like cut, sort, or wash. Say “Cut the paper in half.” The person you are speaking to knows the instruction is for them, so you usually leave out you.\n\nTo tell someone what to avoid, put don’t before the base verb. Say “Don’t cut the blue paper.” You can also use do not, which you often see on signs. A common mistake is to write “Don’t to cut.” After don’t or do not, use cut without to.\n\nYou can add please to make an instruction sound more polite. Put it at the start in “Please wash the cups” or at the end in “Wash the cups, please.” It also works in a negative instruction, as in “Please don’t use the big scissors.” When the craft table is closing, use an imperative to tell people where to put things back.","contrast_text":"“You wash the brushes” can describe what someone usually does. “Wash the brushes” gives that person an instruction.","common_error_pattern":"Learners sometimes put to after don’t or do not. Use “Don’t open the glue” instead of “Don’t to open the glue.”","examples_json":[{"bad":"To cut the card in half.","good":"Cut the card in half."},{"bad":"Please sorts the buttons by color.","good":"Please sort the buttons by color."},{"bad":"Don't to wash the scissors.","good":"Don't wash the scissors."},{"bad":"Please not put wet brushes in the box.","good":"Please don't put wet brushes in the box."}],"tags":["A1","a1-imperatives-at-a-craft-table","imperatives","affirmative imperatives","negative imperatives","please","craft table"]}$seed$::jsonb) r
