    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a1-object-pronouns-in-a-photo-album","title":"Object pronouns in a photo album","level":"A1","status":"published","sort_order":320,"metadata":{},"focus_area":"object-pronouns","explanation_text":"Use an object pronoun after a verb like help, visit, or see. Say “I help him.” I is the person who helps. Him is the person I help.\n\nUse me for yourself and you for the person or people you are speaking to. Use him for one person you call he, and her for one person you call she. Use it for one thing, such as a photo. Use us when you mean yourself and one or more other people. Use them for two or more people or things you are talking about, such as two friends or two photos. You can also use them for one person you call they.\n\nYou can also use these forms after words like to, for, and with. Imagine your group is making a photo album. If you need one file, say “Please send it to us.” It means the file, and us means you and the other people in your group.","contrast_text":"Compare “She helps us” with “We help her.” She and we are subject forms. Us and her are object forms. You and it have the same form as subjects and objects.","common_error_pattern":"A common error is using a subject form after a verb or a preposition when you need an object form, as in “Help I” or “with they.” Say “Help me” and “with them.”","examples_json":[{"bad":"Can you help I with the album?","good":"Can you help me with the album?"},{"bad":"We visit he on Sundays.","good":"We visit him on Sundays."},{"bad":"I have a copy for she.","good":"I have a copy for her."},{"bad":"The photos are ready. Can you print they?","good":"The photos are ready. Can you print them?"}],"tags":["a1-object-pronouns-in-a-photo-album","A1","object pronouns","photo album"]}$seed$::jsonb) r
