  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'a2-manner-adverbs-in-the-practice-room') then
    raise notice 'skipped existing grammar item %', 'a2-manner-adverbs-in-the-practice-room';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a2-manner-adverbs-in-the-practice-room","title":"Adverbs of manner in the practice room","level":"A2","status":"published","sort_order":320,"metadata":{},"focus_area":"adverbs-of-manner","explanation_text":"A manner adverb tells us how someone does something. At an orchestra rehearsal, the players listen carefully and speak quietly. Many manner adverbs end in -ly: careful becomes carefully, quiet becomes quietly, and easy becomes easily. The adverb for good is well. Fast and hard keep the same form: you can play fast or work hard.\n\nUse an adjective after a linking verb such as be or sound when you describe the subject. In “The music sounds good,” good describes the music. In “The orchestra plays well,” well tells us how the orchestra plays. A common mistake is to use good to describe how someone plays.\n\nA common place for a manner adverb is after the action verb when there is no object, as in “They practised quietly.” When the verb has an object, the adverb often comes after it: “They packed their instruments carefully.” You can use the same pattern for everyday tasks: “I folded the shirts carefully.”","contrast_text":"“The hall is quiet” describes the hall. “The players speak quietly” describes how the players speak. In the same way, “The music sounds good” describes the music, and “The orchestra plays well” describes how the orchestra plays.","common_error_pattern":"Using an adjective to say how someone does something, as in “She plays the violin good.” Use the manner adverb well.","examples_json":[{"bad":"The rehearsal room is quietly.","good":"The rehearsal room is quiet."},{"bad":"She plays the violin good.","good":"She plays the violin well."},{"bad":"He carried to the car carefully the cello.","good":"He carried the cello carefully to the car."},{"bad":"The drummer can play that part fastly.","good":"The drummer can play that part fast."}],"tags":["A2","grammar","adverbs of manner","linking verbs","adverb placement","a2-manner-adverbs-in-the-practice-room"]}$seed$::jsonb) r
    returning id into v_parent_id;
