  -- grammar: a2-too-and-enough-for-an-outdoor-kit (A2)
  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'a2-too-and-enough-for-an-outdoor-kit') then
    raise notice 'skipped existing grammar item %', 'a2-too-and-enough-for-an-outdoor-kit';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a2-too-and-enough-for-an-outdoor-kit","title":"Too and enough for an outdoor kit","level":"A2","status":"published","sort_order":320,"metadata":{},"focus_area":"too-and-enough","explanation_text":"Put too before an adjective when something goes past a limit and causes a problem. If your lunch box will not fit in your bag, you can say, “The box is too wide for this bag.” Very wide describes the size. The box may still fit.\n\nPut enough after an adjective when something meets a need. If a blanket keeps you warm on a cool morning, it is warm enough. If you still feel cold under it, it is not warm enough. You can add a purpose, as in “The bag is big enough to hold two towels.”\n\nPut enough before a noun when you have the amount or number you need. Say “enough water” for an amount and “enough cups” for a number. Put enough directly before these nouns. Before a short visit to a lake, check whether your clothes are warm enough, whether anything is too big for your bag, and whether you have enough water for everyone.","contrast_text":"“The flask is very heavy” describes its weight. “The flask is too heavy to carry” says its weight makes carrying it a problem.","common_error_pattern":"A common mistake is to use the same word order everywhere. Say “warm enough” with an adjective and “enough water” with a noun.","examples_json":[{"bad":"These boots are small too for me to wear.","good":"These boots are too small for me to wear."},{"bad":"This coat is enough warm for the morning walk.","good":"This coat is warm enough for the morning walk."},{"bad":"We have enough of napkins for five people.","good":"We have enough napkins for five people."},{"bad":"The water in the flask is too much hot to drink.","good":"The water in the flask is too hot to drink."}],"tags":["a2","a2-too-and-enough-for-an-outdoor-kit","too","enough","outdoor-kit"]}$seed$::jsonb) r
