    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"b2-causatives-for-a-repair-workshop","title":"Causatives in the repair workshop","level":"B2","status":"published","sort_order":320,"metadata":{},"focus_area":"causative-verb-patterns","explanation_text":"Use let when you give someone permission to act, and make when you require them to act. Put the person who does the work directly after let or make, then use the base form of the verb without to. In “The supervisor let the apprentice test the brakes,” the apprentice does the testing.\n\nUse have when you assign a task to someone and get when you persuade someone or manage to arrange for them to act. After have + person, use the base form without to. After get + person, use to + base form.\n\nWhen the focus is on a service you arrange, use have or get + the thing that receives the work + a past participle. For example, “We got the drill repaired” means someone else repaired it for us. A common mistake is to add to after active make, have or let, or to leave it out after get when the next word or phrase names the person doing the work.","contrast_text":"“We had the technician calibrate the gauge” names the technician as the person doing the work. “We had the gauge calibrated” focuses on the service and leaves the technician unnamed. With get, the same contrast is “We got the technician to calibrate the gauge” and “We got the gauge calibrated.”","common_error_pattern":"In active sentences, use the bare infinitive after make, have or let + person, and the to-infinitive after get + person. When have or get is followed by the thing receiving a service, use a past participle.","examples_json":[{"bad":"The foreman made the crew to repeat the pressure test.","good":"The foreman made the crew repeat the pressure test."},{"bad":"The mechanic let me to watch the wheel alignment.","good":"The mechanic let me watch the wheel alignment."},{"bad":"We got the supplier send a replacement seal.","good":"We got the supplier to send a replacement seal."},{"bad":"We had both blades sharpen at a specialist shop.","good":"We had both blades sharpened at a specialist shop."}],"tags":["b2-causatives-for-a-repair-workshop","B2","causatives","bare-infinitive","to-infinitive","past-participle","repair-workshop"]}$seed$::jsonb) r
