    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"b2-question-tags-in-team-briefings","title":"Question tags in team briefings","level":"B2","status":"published","sort_order":320,"metadata":{},"focus_area":"question-tags","explanation_text":"Use a question tag when you think a handoff detail is correct and want a teammate to confirm it. Put the tag after a comma. A positive statement takes a negative tag, and a negative statement takes a positive tag. Use a subject pronoun that refers to the same person or thing as the statement’s subject. When the statement uses be, an auxiliary or a modal, use the corresponding verb in the tag and switch its polarity. If a present or past simple statement has no auxiliary and the main verb is not be, use do, does or did.\n\nUse a positive tag when no or never makes the clause you are checking negative. For example, ‘We stock no spare cables, do we?’ takes a positive tag. Use do because stock is a simple present main verb.\n\nAfter a positive statement with I am, use aren’t I? in ordinary conversation. After I’m not, use am I?\n\nUse shall we? after let’s to invite agreement with a suggestion. At a handoff, ‘Let’s review the open issues, shall we?’ proposes a next step.","contrast_text":"‘You sent the checklist, didn’t you?’ checks an assumption. ‘Did you send the checklist?’ asks directly whether it happened. ‘Let’s review the checklist, shall we?’ invites agreement on what to do next.","common_error_pattern":"A common error is to use a negative tag after never because the statement has no not. In ‘You’ve never tested the backup, have you?’, never makes the statement negative, so the tag is positive.","examples_json":[{"bad":"The handoff notes are ready, aren't it?","good":"The handoff notes are ready, aren't they?"},{"bad":"You've never used the backup link, haven't you?","good":"You've never used the backup link, have you?"},{"bad":"I'm leading the briefing, isn't it?","good":"I'm leading the briefing, aren't I?"},{"bad":"Let's check the contact list, will we?","good":"Let's check the contact list, shall we?"}],"tags":["b2-question-tags-in-team-briefings","B2","question tags","project handoffs"]}$seed$::jsonb) r
