  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c1-fronted-concession-with-as-and-though') then
    raise notice 'skipped existing grammar item %', 'c1-fronted-concession-with-as-and-though';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c1-fronted-concession-with-as-and-though","title":"Fronted concession with as and though","level":"C1","status":"published","sort_order":320,"metadata":{},"focus_area":"fronted-concession","explanation_text":"In formal English, you can put an adjective first to acknowledge a fact before stating a result that might seem surprising. In ‘Fragile as the model was, it survived the journey’, the opening clause means ‘Although the model was fragile’. Put as or though immediately after the adjective, then keep the usual subject–verb order and the tense the context calls for.\n\nAn adverb can go first in the same way. ‘Carefully though we packed the glass, one panel cracked’ acknowledges how we packed it. You can also front a noun that identifies someone’s role. In ‘Novice as she was, she spotted the fault’, the role noun is bare, without the article that appears in ‘Although she was a novice’.\n\nCheck the relationship between the clauses. Concessive as introduces a fact that makes the outcome unexpected. Causal as introduces a reason for the outcome, while as … as compares two things on the same scale.","contrast_text":"‘Unstable as the prototype was, testing continued’ means testing continued despite the instability. ‘As the prototype was unstable, testing stopped’ gives the instability as the reason for stopping. ‘The prototype was as unstable as the previous version’ compares the two versions.","common_error_pattern":"In the bare-noun pattern, change “although he was an apprentice” to “apprentice as he was”. Keep the subject before the verb after as or though.","examples_json":[{"bad":"Fragile as was the model, it survived the journey.","good":"Fragile as the model was, it survived the journey."},{"bad":"Carefully though packed we the glass, one panel cracked.","good":"Carefully though we packed the glass, one panel cracked."},{"bad":"Novice as was she, she spotted the fault.","good":"Novice as she was, she spotted the fault."},{"bad":"Although cramped the booth was, it housed all the recording equipment.","good":"Cramped though the booth was, it housed all the recording equipment."}],"tags":["C1","c1-fronted-concession-with-as-and-though","concession","adjective fronting","adverb fronting","bare noun fronting","formal register"]}$seed$::jsonb) r
