  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c1-only-even-and-focus-in-briefs') then
    raise notice 'skipped existing grammar item %', 'c1-only-even-and-focus-in-briefs';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c1-only-even-and-focus-in-briefs","title":"Only and even: choosing the focus","level":"C1","status":"published","sort_order":320,"metadata":{},"focus_area":"focus-particle-scope","explanation_text":"Use only to rule out relevant alternatives. In “The panel funded only the pilot,” the focus is “the pilot.” The sentence excludes the other proposals under consideration. Use even to single out something especially unexpected. In “The panel funded even the pilot,” funding the pilot was particularly unlikely or surprising in that context.\n\nIn a written brief, placing only or even immediately before the focused phrase often makes the intended reading easier to recover. English also allows these words earlier in the clause. In “The editor only moved the interview to Friday,” context or spoken stress can make “to Friday” the focus, though a reader might take “moved the interview to Friday” as the one action the editor took.\n\nWhen revising, identify the exact phrase you mean to highlight. Then ask what the reader should infer. Are you excluding competing options, or are you drawing attention to an option that runs against expectations? In the examples, the corrections show how to match the intended focus to the context.","contrast_text":"“Only the deputy signed” excludes the other potential signers. “Even the deputy signed” presents the deputy as a particularly unlikely signer. The deputy is the focus in both sentences.","common_error_pattern":"Check which alternatives are excluded. “Only the review board can extend the deadline” restricts who has the authority. “The review board can do only one thing, extend the deadline” restricts the available action.","examples_json":[{"bad":"The annex was the sole document released. Only the press office released the annex.","good":"The annex was the sole document released. The press office released only the annex."},{"bad":"The external auditor was the least likely person to back the proposal. The external auditor backed only the proposal.","good":"The external auditor was the least likely person to back the proposal. Even the external auditor backed the proposal."},{"bad":"The grant is restricted to work carried out after approval. Only the grant covers work carried out after approval.","good":"The grant is restricted to work carried out after approval. The grant covers only work carried out after approval."},{"bad":"The editors expected the photo essay to miss the deadline, but it made the launch alongside the other pieces. The launch schedule includes only the photo essay.","good":"The editors expected the photo essay to miss the deadline, but it made the launch alongside the other pieces. The launch schedule includes even the photo essay."}],"tags":["C1","c1-only-even-and-focus-in-briefs","focus adverbs","only","even","written briefings"]}$seed$::jsonb) r
    returning id into v_parent_id;
