  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c2-anticipatory-it-in-policy-reviews') then
    raise notice 'skipped existing grammar item %', 'c2-anticipatory-it-in-policy-reviews';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c2-anticipatory-it-in-policy-reviews","title":"Anticipatory it in policy reviews","level":"C2","status":"published","sort_order":320,"metadata":{},"focus_area":"anticipatory-it","explanation_text":"Use anticipatory it as the subject when a policy review opens with an evaluation and gives the content of that evaluation later. In “It is regrettable that the consultation excluded tenants,” the that-clause specifies what is regrettable. A to-clause can follow the adjective in the same way: “It is prudent to publish the criteria before applications open.”\n\nAnticipatory it can also occupy the object position after verbs such as find, make and consider. Put the adjective or noun phrase immediately after it, then supply the clause: “The panel found it difficult to verify the estimates” or “The panel considered it a mistake to rely on a single estimate.” A common error is to omit it while keeping the complement and the postponed clause.\n\nCheck the role of it before rewriting. In “The panel revised the policy and published it,” it refers to the policy. In “It was the deadline that the panel revised,” the cleft singles out the deadline. Anticipatory it fills an early subject or object position, and the later clause tells you what is being evaluated. In an it-cleft, the phrase immediately after the form of be receives the focus.","contrast_text":"In “The panel found it impractical to extend the deadline,” the to-clause supplies what the panel found impractical. In “The panel reviewed the extension and found it impractical,” it refers to the extension. In “It was the deadline that the panel extended,” the it-cleft identifies the deadline as the element in focus.","common_error_pattern":"Omitting dummy it while retaining the evaluation and the postponed clause, especially after find, make or consider.","examples_json":[{"bad":"Is regrettable that the consultation excluded tenants.","good":"It is regrettable that the consultation excluded tenants."},{"bad":"It is inadvisable publish the draft before the review closes.","good":"It is inadvisable to publish the draft before the review closes."},{"bad":"The revised timetable made impossible to notify every applicant before the deadline.","good":"The revised timetable made it impossible to notify every applicant before the deadline."},{"bad":"The panel considered a mistake to base the allocation on last year's figures.","good":"The panel considered it a mistake to base the allocation on last year's figures."}],"tags":["c2-anticipatory-it-in-policy-reviews","C2","anticipatory subject","anticipatory object","referential it","it-clefts","formal policy reviews"]}$seed$::jsonb) r
    returning id into v_parent_id;
