  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c2-free-relatives-and-bounded-choice","title":"Fused relatives and bounded choice","level":"C2","status":"published","sort_order":320,"metadata":{},"focus_area":"free-relatives","explanation_text":"Start with what: in ‘We restored what we could save’, what we could save means ‘the material that we could save’. What combines the understood noun and the relative word. The whole expression functions as a noun phrase: it names the material that underwent restoration.\n\nWhoever can mean ‘any person who’, and whatever can mean ‘anything that’. Both can leave the identity open while still imposing a condition: ‘whoever meets the criteria’ leaves the person’s identity open but requires them to qualify. Whichever signals a choice from an identifiable set. In ‘Use whichever of the two finishes the conservator approves’, either finish is eligible for selection, but the choice stays within the named pair.\n\nCompare ‘We will implement whichever plan the board approves’ with ‘We need to establish which plan the board approved’. The first identifies the plan to implement. The second poses an embedded question about the plan’s identity. Even with a named set, an embedded question normally uses which. Keep statement word order inside it: ‘which plan the board approved’. In “whichever mount she considers safer”, the chosen mount is already understood as the object of considers. Do not add it to repeat that object.","contrast_text":"‘Preserve what the team recovered’ refers to the recovered material. ‘Find out what the team recovered’ asks someone to identify what was recovered. The words ‘what the team recovered’ are identical, so use the surrounding verb and the intended meaning to tell the two constructions apart.","common_error_pattern":"Learners sometimes add an explicit antecedent before fused what, as in ‘the material what we recovered’. Use either ‘what we recovered’ or ‘the material that we recovered’. Use which to ask for the identity of a member of a set, stated explicitly or understood from context. For example, “determine which of the two exemptions the board granted”.","examples_json":[{"bad":"The editors published the material what the fact-checkers had verified.","good":"The editors published what the fact-checkers had verified."},{"bad":"Whomever chairs the panel will sign the recommendation.","good":"Whoever chairs the panel will sign the recommendation."},{"bad":"The conservator may use whichever of the two mounts she considers it safer.","good":"The conservator may use whichever of the two mounts she considers safer."},{"bad":"The registrar needs to determine which of the two exemptions did the board grant.","good":"The registrar needs to determine which of the two exemptions the board granted."}],"tags":["C2","c2-free-relatives-and-bounded-choice","fused relatives","free choice","bounded choice","embedded interrogatives"]}$seed$::jsonb) r
    returning id into v_parent_id;
