    from jsonb_populate_record(null::public.vocabulary_deck_words, $seed${"word":"caramelized","part_of_speech":"adjective","definition":"Browned by heating sugars until they develop the flavour of caramel.","example":"The tart had a thin crust of caramelized sugar that tasted of toffee.","translation_ru":"карамелизованный","translation_uz":"shakari qizib karamellashgan","sort_order":14,"collocations":["caramelized onions","caramelized edges","caramelized sugar"],"word_family":[{"word":"caramelize","part_of_speech":"verb"},{"word":"caramelization","part_of_speech":"noun"}]}$seed$::jsonb) r;
    insert into public.learning_content_registry_items (
      product_id, language_id, source_record_id, service_key, content_type, source_table, source_ref, title, description,
      skill_key, subskill_keys, cefr_level, difficulty, estimated_minutes, learning_objective, tags, status, payload_json, metadata
    )
    select v_product_vocabulary, v_en_id, v_parent_id, r.service_key, r.content_type, r.source_table, r.source_ref, r.title, r.description,
      r.skill_key, r.subskill_keys, r.cefr_level, r.difficulty, r.estimated_minutes, r.learning_objective, r.tags, r.status, r.payload_json,
      jsonb_build_object('seeded_by', v_seed)
    from jsonb_populate_record(null::public.learning_content_registry_items, $seed${"service_key":"vocabulary","content_type":"vocabulary.deck","source_table":"vocabulary_decks","source_ref":"c2-sensory-precision-in-food-writing","title":"Sensory precision in food writing","skill_key":"vocabulary","cefr_level":"C2","difficulty":0.9,"status":"published","description":"Practise choosing precise terms for flavour, aroma, texture and mouthfeel in food and drink criticism. Distinguish neutral descriptions from praise and criticism, and notice where the balance of a dish determines the judgement.","subskill_keys":["vocabulary.recall","vocabulary.usage"],"estimated_minutes":6,"learning_objective":"Learn the words in this set, then match each meaning to the right word.","tags":["sensory description"],"payload_json":{"topic":"sensory description","word_count":14}}$seed$::jsonb) r
    on conflict (language_id, service_key, content_type, source_ref) do update set
      source_table = excluded.source_table, source_record_id = excluded.source_record_id, title = excluded.title,
      description = excluded.description, subskill_keys = excluded.subskill_keys, cefr_level = excluded.cefr_level,
      difficulty = excluded.difficulty, estimated_minutes = excluded.estimated_minutes, tags = excluded.tags,
      status = excluded.status, payload_json = excluded.payload_json,
      metadata = coalesce(public.learning_content_registry_items.metadata, '{}'::jsonb) || excluded.metadata, updated_at = now();
  end if;
end
$$;
